class Solution {
public:
    int longestSubsequence(vector<int>& arr, int difference) {
        map<int, int> chain;
        int best = 0;
        for (int i = 0; i < (int)arr.size(); i++) {
            int prev = chain.count(arr[i] - difference) ? chain[arr[i] - difference] : 0;
            chain[arr[i]] = prev + 1;
            best = max(best, chain[arr[i]]);
        }
        return best;
    }
};
